import{_ as d,o as n,a,b as i}from"./app.C41L12d5.js";const s=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"api/appendix/mmad_mx_interface_boundary_value_summary.md","filePath":"api/appendix/mmad_mx_interface_boundary_value_summary.md","outlineHeaders":[{"level":2,"title":"边界值说明","slug":"边界值说明","link":"#边界值说明"},{"level":2,"title":"边界值汇总","slug":"边界值汇总","link":"#边界值汇总"},{"level":3,"title":"INF/NAN模式边界值汇总","slug":"INF/NAN模式边界值汇总","link":"#INF/NAN模式边界值汇总"},{"level":3,"title":"饱和模式边界值汇总","slug":"饱和模式边界值汇总","link":"#饱和模式边界值汇总"}],"lastUpdated":1788166713000}'),r={name:"api/appendix/mmad_mx_interface_boundary_value_summary.md"};function f(l,t,e,o,m,_){return n(),a("div",null,[...t[0]||(t[0]=[i('<div><article class="markdown-body"><h1>MmadMx接口边界值汇总</h1><p>本节汇总介绍了MmadMx计算接口在边界值输入下的输出结果，数据类型见基础API下的<a href="../SIMD-API/basic_api/cube_compute_ISASI/mmad_compute/MmadMx.html#%E6%95%B0%E6%8D%AE%E7%B1%BB%E5%9E%8B">MmadMx</a>，以下内容针对如下型号生效：</p><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT</li></ul></div><h2 id="边界值说明">边界值说明<a class="header-anchor" href="#边界值说明">​</a></h2><ul><li><p>fp4x2_e1m2_t和fp4x2_e2m1_t数据类型没有+inf/-inf/nan定义，从其他数据类型的+inf/-inf/nan转换为这两种数据类型时会被直接转换为边界值或0。值转换情况如下表所示：</p><p><strong>表1</strong> fp4x2_e1m2_t和fp4x2_e2m1_t数据类型边界值转换结果</p><table><thead><tr><th></th><th>+inf</th><th>-inf</th><th>nan</th></tr></thead><tbody><tr><td>fp4x2_e1m2_t</td><td>1.75</td><td>-1.75</td><td>0.0</td></tr><tr><td>fp4x2_e2m1_t</td><td>6</td><td>-6</td><td>0.0</td></tr></tbody></table></li><li><p>fp8_e4m3fn_t数据类型只有nan定义，没有+inf/-inf定义，从其他数据类型的+inf/-inf转换成fp8_e4m3fn_t数据类型时会被转换成nan。</p></li><li><p>MmadMx计算应避免nan输入，否则可能会产生执行报错。</p></li></ul><h2 id="边界值汇总">边界值汇总<a class="header-anchor" href="#边界值汇总">​</a></h2><h3 id="INF/NAN模式边界值汇总">INF/NAN模式边界值汇总<a class="header-anchor" href="#INF/NAN模式边界值汇总">​</a></h3><p><strong>表2</strong> INF/NAN模式MmadMx接口边界值汇总</p><table><thead><tr><th>C矩阵的数据类型</th><th>MmadMx子阶段</th><th>A矩阵的元素取值</th><th>B矩阵的元素取值</th><th>dst的元素取值</th></tr></thead><tbody><tr><td>float</td><td>矩阵乘法阶段</td><td>+inf</td><td>norm(&gt; 0.0)/+inf</td><td>+inf</td></tr><tr><td>float</td><td>矩阵乘法阶段</td><td>+inf</td><td>norm(&lt; 0.0)/-inf</td><td>-inf</td></tr><tr><td>float</td><td>矩阵乘法阶段</td><td>-inf</td><td>norm(&gt; 0.0)/+inf</td><td>-inf</td></tr><tr><td>float</td><td>矩阵乘法阶段</td><td>-inf</td><td>norm(&lt; 0.0)/-inf</td><td>+inf</td></tr><tr><td>float</td><td>矩阵乘法阶段</td><td>+inf/-inf</td><td>0.0</td><td>nan</td></tr><tr><td>float</td><td>矩阵乘法阶段</td><td>norm(&gt; 0.0)</td><td>+inf</td><td>+inf</td></tr><tr><td>float</td><td>矩阵乘法阶段</td><td>norm(&gt; 0.0)</td><td>-inf</td><td>-inf</td></tr><tr><td>float</td><td>矩阵乘法阶段</td><td>norm(&lt; 0.0)</td><td>+inf</td><td>-inf</td></tr><tr><td>float</td><td>矩阵乘法阶段</td><td>norm(&lt; 0.0)</td><td>-inf</td><td>+inf</td></tr><tr><td>float</td><td>矩阵乘法阶段</td><td>0.0</td><td>+inf/-inf</td><td>nan</td></tr><tr><td>float</td><td>矩阵乘法阶段</td><td>nan</td><td>任意输入</td><td>nan</td></tr><tr><td>float</td><td>矩阵乘法阶段</td><td>任意输入</td><td>nan</td><td>nan</td></tr><tr><td>float</td><td>矩阵乘法阶段</td><td>任意输入</td><td>任意输入</td><td>结果溢出情况下：<br>正向溢出为+inf，<br>负向溢出为-inf</td></tr><tr><td>float</td><td>加法阶段</td><td>+inf</td><td>-inf</td><td>-inf</td></tr><tr><td>float</td><td>加法阶段</td><td>+inf</td><td>+inf/norm</td><td>+inf</td></tr><tr><td>float</td><td>加法阶段</td><td>-inf</td><td>+inf</td><td>+inf</td></tr><tr><td>float</td><td>加法阶段</td><td>-inf</td><td>-inf/norm</td><td>-inf</td></tr><tr><td>float</td><td>加法阶段</td><td>nan</td><td>任意输入</td><td>nan</td></tr><tr><td>float</td><td>加法阶段</td><td>任意输入</td><td>nan</td><td>nan</td></tr></tbody></table><h3 id="饱和模式边界值汇总">饱和模式边界值汇总<a class="header-anchor" href="#饱和模式边界值汇总">​</a></h3><ul><li>进行量化计算前会对边界值进行一次饱和处理，随后以数值形式进行MmadMx计算。 <ul><li>nan会被转换为0.0。</li><li>四种入参类型中只有fp8_e5m2_t数据类型具有+inf/-inf定义，会被转换为57344.0/-57344.0。</li></ul></li><li>MmadMx计算结果溢出的情况下根据正负分别饱和为MAX（0x7F7FFFFF）/MIN（0xFF7FFFFF）。</li><li>矩阵乘结果与bias矩阵相加的加法阶段前，bias矩阵中的nan会被转换为0。</li></ul></article></div>',1)])])}const p=d(r,[["render",f]]);export{s as __pageData,p as default};
